sigjmp_buf env;
const int SAVE_MASK = 1;

// sigsetjmp returns 0 on initial call, non-zero on jump return.
// SAVE_MASK (1) ensures the current signal mask is saved.
int ret = sigsetjmp(env, SAVE_MASK);

if (ret == 0) {
    // Initial execution path
    // Signal mask is now saved in 'env'
} else {
    // Execution resumed via siglongjmp(env, value)
    // Saved signal mask is automatically restored
}

// Example jump usage:
// siglongjmp(env, 42);
